class Solution {
public:
    int threeSumClosest(vector<int>& nums, int target) {
        int n = nums.size();
        int closest = nums[0] + nums[1] + nums[2];
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                for (int k = j + 1; k < n; ++k) {
                    int s = nums[i] + nums[j] + nums[k];
                    if (abs(s - target) < abs(closest - target)) {
                        closest = s;
                        if (closest == target) return target;
                    }
                }
            }
        }
        return closest;
    }
};

