class Solution {
public:
    int threeSumClosest(vector<int>& nums, int target) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        int closest = nums[0] + nums[1] + nums[2];
        for (int i = 0; i < n - 2; ++i) {
            for (int j = i + 1; j < n - 1; ++j) {
                int need = target - nums[i] - nums[j];
                auto it = lower_bound(nums.begin() + j + 1, nums.end(), need);
                if (it != nums.end()) {
                    int s = nums[i] + nums[j] + *it;
                    if (abs(s - target) < abs(closest - target)) closest = s;
                }
                if (it != nums.begin() + j + 1) {
                    --it;
                    int s = nums[i] + nums[j] + *it;
                    if (abs(s - target) < abs(closest - target)) closest = s;
                }
                if (closest == target) return target;
            }
        }
        return closest;
    }
};

