import java.util.Arrays;
class Solution {
    public int threeSumClosest(int[] nums, int target) {
        Arrays.sort(nums);
        int n = nums.length;
        int closest = nums[0] + nums[1] + nums[2];
        for (int i = 0; i < n - 2; i++) {
            for (int j = i + 1; j < n - 1; j++) {
                int need = target - nums[i] - nums[j];
                int idx = lowerBound(nums, j + 1, n, need);
                if (idx < n) {
                    int s = nums[i] + nums[j] + nums[idx];
                    if (Math.abs(s - target) < Math.abs(closest - target)) closest = s;
                }
                if (idx - 1 > j) {
                    int s = nums[i] + nums[j] + nums[idx - 1];
                    if (Math.abs(s - target) < Math.abs(closest - target)) closest = s;
                }
                if (closest == target) return target;
            }
        }
        return closest;
    }
    private int lowerBound(int[] nums, int lo, int hi, int val) {
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (nums[mid] < val) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

